DROP TABLE IF EXISTS players; DROP TABLE IF EXISTS solves; DROP TABLE IF EXISTS attempts; CREATE TABLE players (id TEXT PRIMARY KEY, handle TEXT NOT NULL UNIQUE COLLATE NOCASE, created INTEGER NOT NULL); CREATE TABLE solves (player_id TEXT NOT NULL, challenge_id TEXT NOT NULL, points INTEGER NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (player_id, challenge_id)); CREATE TABLE attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, player_id TEXT NOT NULL, ts INTEGER NOT NULL); CREATE INDEX solves_player ON solves (player_id);
